1	import { policyBasePremium } from "./price-list.js";
2	import { type Item } from "./item.js";
3	import { itemRiskSurcharges } from "./item-risk.js";
4	import { policyModifiers } from "./customer-standing.js";
5	import { type Customer } from "./customer.js";
6	import { roundPremiumInMHPCOFavour } from "./mhpco-rounding.js";
7	import { itemInsuranceValue } from "./price-list.js";
8	import { damageReimbursement, payoutCap, type Damage, type Incident } from "./claims.js";
9	
10	export type { Item, Customer };
11	export type { Incident, Damage } from "./claims.js";
12	
13	/** A policy MHPCO has written: what it covers and what it was quoted for. */
14	export interface Policy {
15	  readonly premium: number;
16	  readonly insuranceSum: number;
17	  readonly items: readonly Item[];
18	}
19	
20	/** The settlement of one claim against a policy. */
21	export interface Settlement {
22	  readonly payout: number;
23	  readonly remainingCap: number;
24	}
25	
26	/**
27	 * Writes a policy for the items the customer wishes to insure: the premium they
28	 * owe, and the insurance sum the office's payouts are measured against.
29	 */
30	export function createPolicy(customer: Customer, items: readonly Item[]): Policy {
31	  return {
32	    premium: quote(customer, items),
33	    insuranceSum: items.reduce((sum, item) => sum + itemInsuranceValue(item), 0),
34	    items,
35	  };
36	}
37	
38	/** The insured item a damage report entry refers to. */
39	function damagedItem(policy: Policy, damage: Damage): Item {
40	  const item = policy.items.find((insured) => insured.type === damage.itemType);
41	  if (item === undefined) {
42	    throw new Error(`the policy does not cover an item of type "${damage.itemType}"`);
43	  }
44	  return item;
45	}
46	
47	/** Settles a damage report against a policy MHPCO has written. */
48	export function claim(policy: Policy, incident: Incident): Settlement {
49	  const reimbursement = incident.damages.reduce(
50	    (total, damage) => total + damageReimbursement(damage, damagedItem(policy, damage)),
51	    0,
52	  );
53	  const cap = payoutCap(policy.insuranceSum);
54	  const payout = Math.min(reimbursement, cap);
55	  return { payout, remainingCap: cap - payout };
56	}
57	
58	/** MHPCO adds a flat processing fee to every premium, at the very end. */
59	const PROCESSING_FEE_G = 5;
60	
61	/**
62	 * Assembles the bill in the order the office bills it: the price-list base
63	 * premium of the policy, the risk surcharges its individual items carry, the
64	 * modifiers rated on the policy as a whole, and finally the processing fee.
65	 *
66	 * Each of those amounts is ruled on elsewhere; this function only knows the
67	 * order they are applied in and that the total is rounded once, at the end.
68	 */
69	export function quote(customer: Customer, items: readonly Item[]): number {
70	  const policyBase = policyBasePremium(items);
71	  const premium =
72	    policyBase +
73	    itemRiskSurcharges(items) +
74	    policyModifiers(customer, policyBase) +
75	    PROCESSING_FEE_G;
76	  return roundPremiumInMHPCOFavour(premium);
77	}
