1	/**
2	 * The MHPCO price list: what each insured thing costs before any modifier.
3	 *
4	 * This module owns catalogue knowledge — which item types the office recognises,
5	 * what it insures each for and what base premium it charges — and, inseparably
6	 * from it, the office's coverage ruling: MHPCO insures exactly what its price
7	 * list names, so being absent from the catalogue *is* being uninsurable. All of
8	 * it is one decision revised by one edit (list a broomstick, with its value and
9	 * rate, and it becomes covered), which is why coverage is not a register of its
10	 * own.
11	 *
12	 * It deliberately knows nothing about surcharges, discounts, the processing fee
13	 * or rounding: those are underwriting policy and change for entirely different
14	 * reasons. The building-block discount for alike components is likewise not
15	 * here; this module only supplies the per-component rate the block rule prices
16	 * against.
17	 */
18	
19	import { type Item } from "./item.js";
20	import { componentsBasePremium } from "./component-blocks.js";
21	
22	/** What the price list states about one main item type. */
23	interface PriceListEntry {
24	  readonly insuranceValueG: number;
25	  readonly basePremiumG: number;
26	}
27	
28	/**
29	 * The MHPCO price list for main items. One entry per type the office
30	 * recognises, stating everything the list says about it — so listing a
31	 * broomstick, or revising what a sword is worth, is a single edit here.
32	 */
33	const MAIN_ITEM_PRICE_LIST: Readonly<Record<string, PriceListEntry>> = {
34	  sword: { insuranceValueG: 1000, basePremiumG: 100 },
35	  amulet: { insuranceValueG: 600, basePremiumG: 60 },
36	  staff: { insuranceValueG: 800, basePremiumG: 80 },
37	  potion: { insuranceValueG: 400, basePremiumG: 40 },
38	};
39	
40	/**
41	 * Components — runes, moonstones and their kin — are not listed individually on
42	 * the main price list. MHPCO insures every component at the same value and
43	 * charges one uniform rate per component, whatever a block costs.
44	 */
45	const COMPONENT_INSURANCE_VALUE_G = 250;
46	const COMPONENT_BASE_PREMIUM_G = 25;
47	
48	/**
49	 * What the price list says about a main item — and, in the same step, whether
50	 * MHPCO covers it at all. The office insures only what its list names, so the
51	 * missing entry *is* the refusal; splitting the lookup from the refusal would
52	 * let the two drift apart.
53	 */
54	function mainItemEntry(item: Item): PriceListEntry {
55	  const entry = MAIN_ITEM_PRICE_LIST[item.type];
56	  if (entry === undefined) {
57	    throw new Error(`MHPCO does not insure items of type "${item.type}"`);
58	  }
59	  return entry;
60	}
61	
62	/**
63	 * What MHPCO insures a single item for. Unlike the base premium, this value is
64	 * untouched by any discount: the building block lowers what a policy costs, not
65	 * what its components are insured for.
66	 */
67	export function itemInsuranceValue(item: Item): number {
68	  return isComponent(item) ? COMPONENT_INSURANCE_VALUE_G : mainItemEntry(item).insuranceValueG;
69	}
70	
71	const COMPONENT_TYPES: readonly string[] = ["rune", "moonstone"];
72	
73	function isComponent(item: Item): boolean {
74	  return COMPONENT_TYPES.includes(item.type);
75	}
76	
77	/**
78	 * The base premium of a single item, as the item-specific risk surcharges see
79	 * it: the price list rate for the item on its own, before any building-block
80	 * discount the policy as a whole may earn.
81	 */
82	export function itemBasePremium(item: Item): number {
83	  return isComponent(item) ? COMPONENT_BASE_PREMIUM_G : mainItemBasePremium(item);
84	}
85	
